const path = require('path');

const THEMES_SPECIFIER = 'devextreme/ui/themes';
const RUNTIME_PATH = path.join(__dirname, 'demo-render-signal.runtime.js');

const VIRTUAL_ENTRY_PREFIX = 'demo-render-signal:';
const VIRTUAL_ENTRY_NAMESPACE = 'demo-render-signal';

function toImportPath(filePath) {
  return JSON.stringify(filePath.split(path.sep).join('/'));
}

function createEntryShimSource(entryPath, { tsNoCheck = false } = {}) {
  return `
    ${tsNoCheck ? '// @ts-nocheck\n' : ''}
    // Generated by utils/server/demo-render-signal.js.
    import themes from ${JSON.stringify(THEMES_SPECIFIER)};
    import { signal, signalWhenRendered } from ${toImportPath(RUNTIME_PATH)};

    themes.initialized(function () {
      import(${toImportPath(entryPath)}).then(signalWhenRendered, function (error) {
        console.error('demo failed to load', error);
        signal();
      });
    });
`;
}

function virtualEntryPath(entryPath) {
  return `${VIRTUAL_ENTRY_PREFIX}${entryPath}`;
}

function virtualEntryPlugin({ resolveDir }) {
  return {
    name: 'demo-render-signal:virtual-entry',
    setup(build) {
      build.onResolve({ filter: new RegExp(`^${VIRTUAL_ENTRY_NAMESPACE}:`) }, (args) => ({
        path: args.path.slice(VIRTUAL_ENTRY_PREFIX.length),
        namespace: VIRTUAL_ENTRY_NAMESPACE,
      }));

      build.onLoad({ filter: /.*/, namespace: VIRTUAL_ENTRY_NAMESPACE }, (args) => ({
        contents: createEntryShimSource(args.path),
        loader: 'js',
        resolveDir,
      }));
    },
  };
}

module.exports = {
  THEMES_SPECIFIER,
  createEntryShimSource,
  virtualEntryPath,
  virtualEntryPlugin,
};
